package pe.edu.solucionesweb.tramite.service; import org.springframework.stereotype.Component; import pe.edu.solucionesweb.tramite.model.Tramite;
@Component public class SolicitudTipoTramite implements TipoTramite { public String nombre(){return "Solicitud";} public void validar(Tramite t){ validarComun(t); } static void validarComun(Tramite t){if(t.getAsunto()==null||t.getAsunto().isBlank()) throw new IllegalArgumentException("El asunto es obligatorio.");} }
